mapper.insert:
SELECT TO_CHAR(SEQ_BRD_NO.NEXTVAL) FROM DUAL
INSERT INTO BOARD ( BRD_NO, MBR_CD, BRD_CODE, BRD_TITL_NM, BRD_CONT, BRD_PBLS_DTM, BRD_VW_CNT, BRD_DEL_YN, BRD_CTGRY_GRP_CD , BRD_END_DTM ) VALUES ( #{brdNo}, #{mbrCd}, #{brdCode}, #{brdTitlNm}, #{brdCont}, SYSDATE, 0, 'N', #{brdCtgryGrpCd}
, #{brdEndDtm, jdbcType=TIMESTAMP}
)

mapper.update:
UPDATE BOARD
SET
    BRD_TITL_NM = #{brdTitlNm},
    BRD_CONT = #{brdCont},
    BRD_MOD_DTM = SYSDATE,
    BRD_CTGRY_GRP_CD = #{brdCtgryGrpCd}
    
        , BRD_END_DTM = #{brdEndDtm, jdbcType=TIMESTAMP}
    
WHERE
    BRD_NO = #{brdNo}
    AND BRD_DEL_YN = 'N'

UPDATE FAQ
SET
    FAQ_CTGRY = #{faqCtgry}
WHERE
    FAQ_ID = #{faqId}

UPDATE NOTICE
SET
    NOTICE_TYPE = #{noticeType}
WHERE
    NOTICE_NO = #{brdNo}

UPDATE BOARD SET BRD_DEL_YN = 'Y', BRD_MOD_DTM = SYSDATE WHERE BRD_NO IN
#{brdNo}
AND BRD_DEL_YN = 'N'

mapper.select:
SELECT COUNT(*) FROM BOARD WHERE BRD_DEL_YN = 'N'
AND BRD_CODE = #{detailSearch.brdCode}
AND (BRD_END_DTM IS NULL OR BRD_END_DTM >= TRUNC(SYSDATE))
